import * as T from './vendor/three.module.js';
import {tops,bottoms} from './outfits.js';
export function createPlayerAvatar(style){const g=new T.Group(),geo=new T.BoxGeometry(1,1,1);function box(x,y,z,w,h,d,color,parent=g){const m=new T.Mesh(geo,new T.MeshLambertMaterial({color}));m.position.set(x,y,z);m.scale.set(w,h,d);parent.add(m);return m;}
 const shirt=box(0,.97,0,.5,.6,.3,0x33a99b);box(0,1.45,0,.38,.38,.36,0xe5b68d);for(const x of [-.32,.32])box(x,.94,0,.14,.55,.16,0xe5b68d);const legs=[-.14,.14].map(x=>box(x,.35,0,.2,.65,.22,0x354d69));const skirt=box(0,.58,0,.56,.4,.38,0x9163a3);for(const x of [-.1,.1]){box(x,1.49,-.19,.055,.06,.025,0x263e38);box(x,1.51,-.21,.018,.02,.01,0xffffff);}box(0,1.37,-.19,.12,.025,.018,0x9e5554);box(0,1.44,-.21,.035,.045,.025,0xd39b77);
 const hair=new T.Group();g.add(hair);const hat=new T.Group();g.add(hat);box(0,1.74,0,.43,.18,.43,0xd4b178,hat);const brim=box(0,1.65,-.08,.65,.06,.65,0xd4b178,hat);const detail=box(0,1.02,-.16,.1,.4,.02,0xffefd0);const skinLegs=[-.14,.14].map(x=>box(x,.15,0,.18,.3,.2,0xe5b68d));
 const stripes=new T.Group();g.add(stripes);for(let i=0;i<3;i++)box(0,.82+i*.12,-.16,.5,.045,.02,0xfff4da,stripes);const collar=new T.Group();g.add(collar);for(const x of [-.1,.1]){const m=box(x,1.19,-.18,.13,.16,.025,0xffefd0,collar);m.rotation.z=x>0?.5:-.5;}const badge=box(.13,1,-.18,.12,.12,.035,0x98e3dd);badge.rotation.z=Math.PI/4;
 function refresh(){shirt.material.color.set(style.top==='tee'?style.color:tops.find(i=>i.id===style.top)?.color||0x33a99b);const pants=bottoms.find(i=>i.id===style.bottom);for(const leg of legs){leg.material.color.set(pants?.color||0x354d69);leg.scale.y=style.bottom==='shorts'?.35:.65;leg.position.y=style.bottom==='shorts'?.5:.35;}skinLegs.forEach(m=>m.visible=style.bottom==='shorts');skirt.visible=style.bottom==='skirt';detail.visible=['jacket','safari'].includes(style.top);stripes.visible=style.top==='sun';collar.visible=['jacket','safari'].includes(style.top);badge.visible=style.top==='crystal';hair.children.forEach(m=>m.material.dispose());hair.clear();const c=0x624632;box(0,1.66,.025,.42,.12,.4,c,hair);if(style.hair==='bob')for(const x of [-.2,.2])box(x,1.48,.04,.1,.38,.36,c,hair);if(style.hair==='ponytail'){box(0,1.52,.24,.15,.3,.25,c,hair);box(0,1.28,.3,.14,.3,.15,c,hair);}if(style.hair==='crest')box(0,1.8,-.07,.15,.2,.3,c,hair);if(style.hair==='curls')for(let i=0;i<5;i++)box((i-2)*.09,1.7+(i%2)*.07,-.1,.12,.12,.2,c,hair);hat.visible=!!style.accessory;hat.children.forEach(m=>m.material.color.set(style.accessory==='cap'?0x39c9c7:0xd4b178));brim.scale.set(style.accessory==='cap'?.43:.65,.06,style.accessory==='cap'?.5:.65);}
 refresh();return {g,refresh};}
export function createPlayerPreview(canvas){const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,1.5));const scene=new T.Scene(),camera=new T.PerspectiveCamera(34,1,.1,15);scene.add(new T.HemisphereLight(0xffffff,0x637158,2.7));let model;return {draw(style,face=true){if(model){scene.remove(model);model.traverse(o=>{if(o.isMesh)o.material.dispose();});const geos=new Set();model.traverse(o=>{if(o.isMesh)geos.add(o.geometry);});geos.forEach(g=>g.dispose());}model=createPlayerAvatar(style).g;scene.add(model);const width=Math.max(220,canvas.clientWidth||280),height=Math.max(240,canvas.clientHeight||300);renderer.setSize(width,height,false);camera.aspect=width/height;camera.position.set(face?0:2.1,1.5,-3.5);camera.lookAt(0,.95,0);camera.updateProjectionMatrix();renderer.render(scene,camera);}};}
